// familyOrder is the strip/guide order: hub-linked first, TALON last.
var familyOrder = []string{"PHOENIX", "SCRIBE", "HEARTH", "HERALD", "BENCH", "LANTERN", "KEEPER", "TALON"}

func infoFor(prog string) progInfoDef {
	if d, ok := progInfo[strings.ToUpper(prog)]; ok {
		return d
	}
	return progInfoDef{Title: prog, Device: "-", Role: "AEGIS family program.", Connect: "-", Sends: "-"}
}

// artImage renders a glyph ONCE to a bitmap (144x144) and caches it.
// Painting 2,304 individual cells per badge per frame was the
// dashboard's biggest CPU cost; a cached image is one GPU quad.
var artImgCache sync.Map // prog -> *image.NRGBA

func artImage(prog string) *image.NRGBA {
	prog = strings.ToUpper(prog)
	if v, ok := artImgCache.Load(prog); ok {
		return v.(*image.NRGBA)
	}
	def, ok := progArt[prog]
	if !ok {
		def = progArt["PHOENIX"]
	}
	n := len(def.grid)
	const scale = 3 // 48 * 3 = 144px master
	img := image.NewNRGBA(image.Rect(0, 0, n*scale, n*scale))
	for y, row := range def.grid {
		for x := 0; x < len(row) && x < n; x++ {
			col, ok := def.pal[row[x]]
			if !ok {
				continue
			}
			for dy := 0; dy < scale; dy++ {
				for dx := 0; dx < scale; dx++ {
					img.SetNRGBA(x*scale+dx, y*scale+dy, col)
				}
			}
		}
	}
	artImgCache.Store(prog, img)
	return img
}

// drawProgArt draws one program glyph at the given cell size (dp per
// authored 24-grid pixel; on-screen size unchanged since the 24 era).
func drawProgArt(gtx layout.Context, prog string, cell unit.Dp) layout.Dimensions {
	total := int(gtx.Dp(cell) * 24)
	if total < 1 {
		total = 1
	}
	size := image.Pt(total, total)
	g := gtx
	g.Constraints = layout.Exact(size)
	widget.Image{Src: paint.NewImageOp(artImage(prog)), Fit: widget.Cover}.Layout(g)
	return layout.Dimensions{Size: size}
}

// artBadge draws the glyph on a softly tinted rounded tile in the
// program's accent color, like an app icon.
func (u *UI) artBadge(gtx layout.Context, prog string, cell unit.Dp) layout.Dimensions {
	accent := accentNRGBA(prog)
	side := int(gtx.Dp(cell) * 24) // authored-pixel footprint; HD grid inside
	sz := image.Pt(side, side)
	bg := color.NRGBA{accent.R / 5, accent.G / 5, accent.B / 5, 0xFF}
	r := side / 5
	if r > side/2 {
		r = side / 2
	}
	paint.FillShape(gtx.Ops, bg, clip.RRect{
		Rect: image.Rectangle{Max: sz}, NW: r, NE: r, SE: r, SW: r,
	}.Op(gtx.Ops))
	_ = drawProgArt(gtx, prog, cell)
	return layout.Dimensions{Size: sz}
}

// gotoProgram jumps to the most useful page for a family member:
// Live Monitor when it is streaming, otherwise its Library entry,
// otherwise Reports.
func (u *UI) gotoProgram(prog string) {
	prog = strings.ToUpper(prog)
	if _, ok := u.core.Live.Get(prog); ok {
		u.selProg = prog
		u.page = pgLive
		return
	}
	for _, dp := range u.core.Store.Summaries() {
		if strings.EqualFold(dp.Prog, prog) {
			u.libDay, u.libProg = dp.Day, dp.Prog
			u.page = pgLibrary
			return
		}
	}
	u.page = pgReports
}
